      const medDate = new Intl.DateTimeFormat("en-US", { dateStyle: "medium", timeZone: "UTC" }).format(d);
      const fullDay = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric", timeZone: "UTC" }).format(d);
      return {
        timeShort,
        timeShortCodes: Array.from(timeShort).map(c => c.charCodeAt(0)),
        datetimeShort,
        datetimeShortCodes: Array.from(datetimeShort).map(c => c.charCodeAt(0)),
        shortDate,
        medDate,
        fullDay
      };
    JS
    pp res
  ensure
    driver.quit
  end
'

